import 'package:flutter/material.dart';
class ActionsScreen extends StatelessWidget{const ActionsScreen({super.key,required this.openMyWork,required this.openModule});final VoidCallback openMyWork;final void Function(String) openModule;@override Widget build(BuildContext context){final actions=[('Check-In / Out',Icons.location_on_outlined,openMyWork),('Create New Order',Icons.shopping_cart_checkout,openMyWork),('Evening Closing',Icons.nightlight_outlined,openMyWork),('Start Field Visit',Icons.route_outlined,openMyWork),('Apply Leave',Icons.event_available_outlined,openMyWork),('Counter Sale',Icons.point_of_sale,()=>openModule('sales')),('Stock Transfer',Icons.swap_horiz,()=>openModule('inventory')),('Purchase Entry',Icons.local_shipping_outlined,()=>openModule('purchase')),('Expense Entry',Icons.receipt_long_outlined,()=>openModule('finance'))];return ListView(padding:const EdgeInsets.all(16),children:[Text('Quick Actions',style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:12),GridView.builder(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),gridDelegate:const SliverGridDelegateWithMaxCrossAxisExtent(maxCrossAxisExtent:220,mainAxisExtent:110,crossAxisSpacing:10,mainAxisSpacing:10),itemCount:actions.length,itemBuilder:(_,i){final a=actions[i];return Card(child:InkWell(borderRadius:BorderRadius.circular(12),onTap:a.$3,child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(a.$2),const Spacer(),Text(a.$1,style:Theme.of(context).textTheme.titleSmall)]))));})]);}}
